class Solution:
    def generateSchedule(self, tasks: List[str], cooldown: int) -> int:
        # Minimum time to finish all tasks respecting cooldown between identical tasks
        # Each task takes 1 unit of time
        # Idle time is inserted if identical task repeats before cooldown finishes
        last_pos = {}
        curr_time = 0

        for task in tasks:
            if task in last_pos:
                # Next execution of task cannot be before last_pos[task] + cooldown + 1
                curr_time = max(curr_time, last_pos[task] + cooldown + 1)
            else:
                curr_time += 1
            last_pos[task] = curr_time

        return curr_time
