#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int generateSchedule(std::vector<std::string>& tasks, int cooldown) {
        std::unordered_map<std::string, int> last_pos;
        int curr_time = 0;

        for (const auto& task : tasks) {
            if (last_pos.count(task)) {
                curr_time = std::max(curr_time + 1, last_pos[task] + cooldown + 1);
            } else {
                curr_time++;
            }
            last_pos[task] = curr_time;
        }
        return curr_time;
    }
};

import java.util.*;

class Solution {
    public int generateSchedule(String[] tasks, int cooldown) {
        Map<String, Integer> lastPos = new HashMap<>();
        int currTime = 0;

        for (String task : tasks) {
            if (lastPos.containsKey(task)) {
                currTime = Math.max(currTime + 1, lastPos.get(task) + cooldown + 1);
            } else {
                currTime++;
            }
            lastPos.put(task, currTime);
        }
        return currTime;
    }
}

var generateSchedule = function(tasks, cooldown) {
    const lastPos = new Map();
    let currTime = 0;

    for (const task of tasks) {
        if (lastPos.has(task)) {
            currTime = Math.max(currTime + 1, lastPos.get(task) + cooldown + 1);
        } else {
            currTime++;
        }
        lastPos.set(task, currTime);
    }
    return currTime;
};
